{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("case must contain threshold and calls")

    threshold = case["threshold"]
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    threshold = float(threshold)
    if not math.isfinite(threshold):
        raise ValueError("threshold must be finite")

    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    diagnostics = []
    accepted_call_ids = []
    required = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )

    for call in calls:
        if not isinstance(call, dict) or any(field not in call for field in required):
            raise ValueError("each call must contain all required fields")

        call_id = call["call_id"]
        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")

        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        for value, name in ((loss_without, "loss_without_call"), (loss_with, "loss_with_call")):
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(name + " must be a number")
            if not math.isfinite(float(value)):
                raise ValueError(name + " must be finite")

        prediction_tokens = call["prediction_tokens"]
        if (isinstance(prediction_tokens, bool) or
                not isinstance(prediction_tokens, int) or
                prediction_tokens < 0):
            raise ValueError("prediction_tokens must be a nonnegative integer")

        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be a boolean")

        normalized_gain = (float(loss_without) - float(loss_with)) / max(1, prediction_tokens)
        accepted = parseable and normalized_gain >= threshold
        diagnostic = {
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": round(normalized_gain, 6),
        }
        diagnostics.append(diagnostic)
        if diagnostic["accepted"]:
            accepted_call_ids.append(diagnostic["call_id"])

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
